actions.script:
// aggregation sums are decimals on Postgres and numbers on OpenSearch; the projection works in numbers
const num = (value) => value == null ? 0 : (typeof value === 'number' ? value : toDecimal(value).toNumber())
const notIn = (name, values) => ({field: {name: name, op: 'in', values: values, negate: true}})
const missingOrBefore = (name, millis) => ({bool: {any: [{field: {name: name, op: 'exists', negate: true}},
        {field: {name: name, op: 'range', lte: millis}}]}})
const estThruMillis = estThruDate ? Number(estThruDate) : null
infoByProductId = {}

// the sums per product of one document type, set on that product's map in infoByProductId
function sumsByProduct(documentType, clauses, sumFields) {
    clauses = [{field: {name: 'productId', op: 'in', values: productIdList}}].concat(clauses)
    if (facilityId) clauses.push({field: {name: 'facilityId', op: 'eq', value: facilityId}})
    const sums = {}
    for (const [name, field] of Object.entries(sumFields)) sums[name] = {sum: {field: field}}
    const result = ec.search.aggregate({documentType: documentType, filter: {bool: {all: clauses}},
            aggs: {products: {terms: {field: 'productId', size: maxResults}, aggs: sums}}})
    for (const bucket of result.products.buckets) {
        const infoMap = infoByProductId[bucket.key] || (infoByProductId[bucket.key] = {})
        for (const name of Object.keys(sumFields)) infoMap[name] = num(bucket[name])
    }
}

if (!ec.search.isAvailable()) { ec.message.addMessage("Search is not configured, no projected inventory", "danger"); return }

if (getOrderItemData) {
    const clauses = [notIn('partStatusId', ['OrderCompleted', 'OrderRejected', 'OrderCancelled'])]
    if (estThruMillis != null) clauses.push(missingOrBefore('requiredByDate', estThruMillis))
    sumsByProduct(orderItemDocumentName, clauses,
            {orderQuantitySum:'orderQuantity', quantityReservedSum:'reservations.quantityReserved',
             quantityNotAvailableSum:'reservations.quantityNotAvailable', quantityNotIssuedSum:'reservations.quantityNotIssued'})
}

if (getProdEstimateData) {
    // ready from the start of today through estThruDate, if there is one
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const readyRange = {name: 'readyDate', op: 'range', gte: today.getTime()}
    if (estThruMillis != null) readyRange.lte = estThruMillis
    sumsByProduct(prodEstimateDocumentName, [{field: readyRange}], {prodEstQuantitySum:'prodEstQuantity'})
}

if (getAssetData) {
    sumsByProduct(assetDocumentName, [{field: {name: 'statusId', op: 'eq', value: 'AstAvailable'}}],
            {availableToPromiseTotalSum:'availableToPromiseTotal', quantityOnHandTotalSum:'quantityOnHandTotal'})
}

if (getRunConsumeData) {
    const clauses = [notIn('statusId', ['WeComplete', 'WeClosed', 'WeCancelled'])]
    if (estThruMillis != null) clauses.push(missingOrBefore('estimatedStartDate', estThruMillis))
    sumsByProduct(runConsumeDocumentName, clauses,
            {estimatedConsumeQuantitySum:'estimatedConsumeQuantity', consumeQuantitySum:'issuances.consumeQuantity'})
}

if (getRunProduceData) {
    const clauses = [notIn('statusId', ['WeComplete', 'WeClosed', 'WeCancelled'])]
    if (estThruMillis != null) clauses.push(missingOrBefore('estimatedStartDate', estThruMillis))
    sumsByProduct(runProduceDocumentName, clauses,
            {estimatedProduceQuantitySum:'estimatedProduceQuantity', produceQuantitySum:'receipts.produceQuantity'})
}

const sumNames = ['orderQuantitySum', 'quantityReservedSum', 'quantityNotAvailableSum', 'quantityNotIssuedSum',
        'prodEstQuantitySum', 'availableToPromiseTotalSum', 'quantityOnHandTotalSum', 'estimatedConsumeQuantitySum',
        'consumeQuantitySum', 'estimatedProduceQuantitySum', 'produceQuantitySum']
for (const infoMap of Object.values(infoByProductId)) {
    for (const name of sumNames) if (infoMap[name] == null) infoMap[name] = 0

    infoMap.orderNotReserved = infoMap.orderQuantitySum - infoMap.quantityReservedSum
    infoMap.estRunConsumeRemaining = Math.max(infoMap.estimatedConsumeQuantitySum - infoMap.consumeQuantitySum, 0)
    infoMap.estRunProduceRemaining = Math.max(infoMap.estimatedProduceQuantitySum - infoMap.produceQuantitySum, 0)

    infoMap.totalProjected = infoMap.availableToPromiseTotalSum - infoMap.orderNotReserved -
            infoMap.estRunConsumeRemaining + infoMap.estRunProduceRemaining + infoMap.prodEstQuantitySum
}

// aggregation metrics are decimals on Postgres and numbers on OpenSearch; the summaries work in numbers
const num = (value) => value == null ? 0 : (typeof value === 'number' ? value : toDecimal(value).toNumber())
infoByProductId = {}
if (!ec.search.isAvailable()) { ec.message.addMessage("Search is not configured, no price history", "danger"); return }

const clauses = [{field: {name: 'productId', op: 'in', values: productIdList}},
        {field: {name: 'partStatusId', op: 'in', values: ['OrderRejected', 'OrderCancelled'], negate: true}}]
if (facilityId) clauses.push({field: {name: 'facilityId', op: 'eq', value: facilityId}})
// alternative to allow placedDate to be null: an any of placedDate missing or in range
const placedRange = {name: 'placedDate', op: 'range', lte: Number(thruDate)}
if (fromDate) placedRange.gte = Number(fromDate)
clauses.push({field: placedRange})

const result = ec.search.aggregate({documentType: orderItemDocumentName, filter: {bool: {all: clauses}},
        aggs: {products: {terms: {field: 'productId', size: maxResults}, aggs: {
            orderQuantitySum: {sum: {field: 'orderQuantity'}},
            unitAmountMin: {min: {field: 'unitAmount'}},
            unitAmountMax: {max: {field: 'unitAmount'}},
            weightedAmountSum: {sum: {field: 'orderItemTotal'}}}}}})

// consolidate the results into a single Map by productId
for (const bucket of result.products.buckets) {
    const orderQuantitySum = num(bucket.orderQuantitySum)
    const weightedAmountSum = num(bucket.weightedAmountSum)
    // rounded to 2 places, half up; zero when there is no quantity
    const weightedAmountAvg = orderQuantitySum === 0 ? 0 : Math.round((weightedAmountSum / orderQuantitySum) * 100) / 100
    infoByProductId[bucket.key] = {orderQuantitySum: orderQuantitySum, unitAmountMin: num(bucket.unitAmountMin),
            unitAmountMax: num(bucket.unitAmountMax), weightedAmountSum: weightedAmountSum,
            weightedAmountAvg: weightedAmountAvg}
}
